order:
struct H{values:u16[2]}
struct C{target:H&}
var source:u16[2]=[77,88];
recursive fn get(c:C&,next:H&)->u16[2]&{c.target .= next;return source;}
fn main(){var first:H=H{values:[1,2]};var second:H=H{values:[3,4]};var c:C=C{target:first};c.target.values=get(c,second);assert(first.values[0]==77);assert(second.values[0]==3);assert(c.target .== &second);print("order");}

fat_order:
struct H{values:u16[2]}
struct C{target:H&}
var source:u16[2]=[77,88];
recursive fn get(c:C&,next:H&)->u16[2]&{c.target .= next;return source;}
fn main(){var first:H[]=[H{values:[1,2]}];var second:H[]=[H{values:[3,4]}];var c:C=C{target:first[0]};c.target.values=get(c,second[0]);assert(first[0].values[0]==77);assert(second[0].values[0]==3);assert(c.target .== &second[0]);print("fat_order");}

fat_refs:
struct H{values:u16[3]}
recursive fn set(dst:u16[3]&,src:u16[3]&){dst=src;}
fn main(){var a:H[]=[H{values:[1,2,3]}];var b:H[]=[H{values:[7,8,9]}];set(a[0].values,b[0].values);assert(a[0].values[2]==9);var refs:u16[3]&[2]=[a[0].values,b[0].values];b[0].values[0]=11;refs[0]=refs[1];assert(a[0].values[0]==11);assert(refs[0] .== &a[0].values);print("fat_refs");}

empty_effect:
var source:u8[0]=[];var calls:i64=0;
recursive fn get()->u8[0]&{calls++;return source;}
fn main(){var target:u8[0]=[];target=get();assert(calls==1);assert(&target .!= &source);print("empty_effect");}
